    (45::BIGINT, 'pésimo profesor, hace todo con ia y pretende que sus estudiantes no hagan lo mismo'::TEXT, 6.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2026-10-14T00:00:00+00:00'::TIMESTAMPTZ, '21f3ef85563d3c67fe0665ae52815643da3eec69fc256caeed8fc159eaa0e100'::TEXT, ARRAY[92]::BIGINT[]),
    (45::BIGINT, 'Es un buen profe. Los exámenes son muy parecidos a las prácticas y si estudia, seguro le va muy bien.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a0a25f157fcc3ee04c0e15a91885a5ac3356a95ad90ed622045a53eff239e88a'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Muy buen profe. Explica los temas de forma clara. Sin embargo como a la mitad del semestre comenzó a poner sólo prácticas y casi no explicaba. Lo recomiendo, se aprende mucho con él.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, '52344e8ffad36e9cc0bc2a7b21ea5a441e38d30383c21af81bfaa2c1e28b1a8b'::TEXT, ARRAY[3575]::BIGINT[]),
    (45::BIGINT, 'Es uno de los mejores profesores de la Escuela. Explica muy bien, de tanta práctica los exámenes son fáciles. Sabe bastante de los temas de contabilidad y finanzas; excelente profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-07-31T00:00:00+00:00'::TIMESTAMPTZ, 'a0c7c3fb743953804ef9cd499d072e16a4d9c21dd0714ba54df8ad4a8d8d5ddd'::TEXT, ARRAY[2689]::BIGINT[]),
    (45::BIGINT, 'José Prado es un excelente profesor. Las clases fueron bastante productivas y siempre le entendí todo. Explica muy bien y todas sus prácticas son muy parecidas al examen. Muy bueno, recomendado!'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2019-12-22T00:00:00+00:00'::TIMESTAMPTZ, '913cc0247ef9c6c3feca6e6d78e6d8e65519a6ad9d08313811d9aedb1c069d4a'::TEXT, ARRAY[2689]::BIGINT[]),
    (45::BIGINT, 'Es un excelente profesor, se realiza tanta práctica que a la hora del examen uno lo hace por memoria. Sabe un MONTÓN de conta y es verdaderamente un profesional.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-05-31T00:00:00+00:00'::TIMESTAMPTZ, '86aaaa734d185b322ba8161029ffd49138f1f7e6bb1fec43cc5ac68a08fabc7d'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'es EL profe, es demasiado buenp, lo hace practicar bastante y evacua todas las dudas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-12-04T00:00:00+00:00'::TIMESTAMPTZ, '6373c9125b5bffbd742da3970e2a947784aba76828fdf8e68af5f7d80715210c'::TEXT, ARRAY[2394, 1707]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-05T00:00:00+00:00'::TIMESTAMPTZ, 'ee368b5c8e2f28f72a4d07360224735db0d3c52f56b85770cc9552a0ac360868'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Excelente profe!! El mejor de todo, hace que la conta sea bonita, inclusive si no nos gusta. Exámenes un poquillo rudos. Por lo que hay que evacuar totalmente las dudas antes del examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-28T00:00:00+00:00'::TIMESTAMPTZ, '5a616225d7c5b9126485a33ea5ed055e9a3ffedbad934f95c89c8e6acf38e2d8'::TEXT, ARRAY[294]::BIGINT[]),
