    (45::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'ba5fe557e6384480b2ef968b769c36d9a39954d210bda10294a0fe68f23e1c07'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-18T00:00:00+00:00'::TIMESTAMPTZ, '2c0443e55392ee9e3b17708edbed6291ea1e97fe1626f1c653063dc24bd06db5'::TEXT, ARRAY[2394, 1707]::BIGINT[]),
    (45::BIGINT, 'En general es un buen profe, brinda apoyo si uno lo solicita y deja muchos ejercicios de tarea lo cual ayuda a ir más preparado al examen. Sin embargo el principal problema es que da muy poco tiempo para resolver el examen que incluye varios ejercicios, y nunca accede a extender el tiempo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Deja trabajos largos']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '24205f56b2f33f075f10aa7bc274c05df7677650d6b6fba483ba337c48ddb636'::TEXT, ARRAY[2394]::BIGINT[]),
    (45::BIGINT, 'El profe sabe mucho, pero por ratos va un toque rápido. Sin embargo, si uno se pierde tiene mucha paciencia. Llama al azar lo cual a veces no es conveniente asi que intente ir al ritmo de él lo cual puede ser complicado. En general buen profe, se aprende bastante y los examenes son fáciles.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Muchos proyectos grupales']::TEXT[], '2022-01-29T00:00:00+00:00'::TIMESTAMPTZ, 'e66f39a285e4d208dbbbc07e4ba2af520a4696db027bdbad75870647bf3d2103'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Excelente profesor, explica muy bien, se adaptó de buena manera a la virtualización. Le gusta llamar al azar a diferentes personas para que participen, entonces esté atento. Pero lo recomiendo al 100%, muchas prácticas y los examenes son parecidas a estas y califica justo. Creo que es de los mejores'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, 'd49c0cd060d4648964a20389e60031b0e8b9a8ea22cd132fcca7d16164480bb5'::TEXT, ARRAY[276]::BIGINT[]),
    (45::BIGINT, 'Con Prado se aprende demasiado. Es un excelente profesor y el curso no se vuelve pesado. Muy tranquilo y buena gente. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-16T00:00:00+00:00'::TIMESTAMPTZ, '661fcd3e610e726ba7e1e33ac1e0fccf68ba53596be90e43ddbc936fbf973b0e'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Excelente profesor ademas de que califica suave y uno aprende con él.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-15T00:00:00+00:00'::TIMESTAMPTZ, '8ae16f5689daa0c662a80826176ae990c638173440f469c3d7e2cbdbfeec6505'::TEXT, ARRAY[2366]::BIGINT[]),
    (45::BIGINT, 'Califica suave, buen profe'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-29T00:00:00+00:00'::TIMESTAMPTZ, 'dc6faa2360202c5267160a437db2cf2f702f287b607aaf8b0a5f71171be653fc'::TEXT, ARRAY[1707, 2394, 289, 294]::BIGINT[]),
