    (45::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2017-06-13T00:00:00+00:00'::TIMESTAMPTZ, '6a21fff602c61c3a45b6d7f3a56ace1b1be763276610c1db95daacf0894fa6a1'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Excelente profe. Muy buena gente y explica súper bien. Se aprende bastante.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-06-09T00:00:00+00:00'::TIMESTAMPTZ, '00b01869dddcdee03f17704b2e7c92bc3dfcb174ef4ab1b3232994766d1487de'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'buen culo y explica bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases excelentes']::TEXT[], '2017-05-12T00:00:00+00:00'::TIMESTAMPTZ, 'a423a0ee38004bfd6d60bfa430bced90a40a6e8bfdab909d4536f6b46539faa3'::TEXT, ARRAY[1707, 2394]::BIGINT[]),
    (45::BIGINT, 'Él es el mejor profe de Conta.. Explica bien, no califica duro y hasta da clases de reposicion sabados..'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '28adfcdf51fc74a00b454893ade730f219472b07ab1af31f247540b9d861a6f7'::TEXT, ARRAY[294]::BIGINT[]),
    (45::BIGINT, 'Una persona muy serena y con bastante claridad a la hora de explicar materia y paciencia infinita para las práctica, todas las semanas dejaba dos: una práctica y una tareas, todas la revisaba. Nos daba clases de apoyo los sabados sin obligación y por iniciativa propia.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, '20b8b17bc7e541ce1c34feb32c8fc1e6dec852c5e64de581882aa989fdbe2f37'::TEXT, ARRAY[294]::BIGINT[]),
    (45::BIGINT, 'No le entendi nada porque no explicaba antes de la practica, cuando revisaba las practicas parecia como si fuera la primera vez que la ve, no revisaba avnaces de proyecto, deja mucha practica, pero si usted es de esos que ocupa que le expliquen paso a paso el no lo hace como hasta al final del tema.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5f0d38150eaacd4270ae272457522f2ddbd6b84dddada751ebdec3a8a214bbfb'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-02T00:00:00+00:00'::TIMESTAMPTZ, '047abbd0ef2baaba52d09f1a320a531913c78e51501b04594208b25aa46dea9d'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-19T00:00:00+00:00'::TIMESTAMPTZ, '4cfef3858a5db8ade9b7d55198c3cb0713270b8a4ebe0570230455aa97f7ce25'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Excelente...'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-06-11T00:00:00+00:00'::TIMESTAMPTZ, '4eed4f949d24c975fcd2034eb3bc89faa7e49682a844be3a97e392b8d7309821'::TEXT, ARRAY[2366]::BIGINT[]),
    (45::BIGINT, 'Muy buen profesor. Deja mucha práctica la cual revisa en clase con mucho detalle. Además atiende todas las consultas de manera oportuna. De los mejores profesores con los que he tenido la oportunidad de llevar un curso.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-29T00:00:00+00:00'::TIMESTAMPTZ, 'a49ebc089ea3e6cd91b4a2c9187ca25ff3cb761e552bc0a6aabc0c6334360b0d'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Excelente Profesor, sino el mejor con el que he recibido Conta, deja mucha practica y eso te ayuda en el examen, ademas es muy buena gente, habla poco, pero es muy claro cuando dá las clases, además se preocupa porque uno entienda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-05-25T00:00:00+00:00'::TIMESTAMPTZ, '0edb527df6f758d8aaacc76c79f147ad5d6a5c97eb544f71d2d439087c4a9630'::TEXT, ARRAY[1707, 2394]::BIGINT[]),
    (45::BIGINT, 'En mi opinión es el mejor profesor de contabilidad que hay en el TEC.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-02-10T00:00:00+00:00'::TIMESTAMPTZ, '8fb12916e37f23f19e32158252c28a1206f7d460c095c43936f79907b0c4d08d'::TEXT, ARRAY[1707, 2394]::BIGINT[]),
    (45::BIGINT, 'Excelente profe.. Pura vida y sobre todo, se preocupa porque de verdad entiendas la matería.. Realiza bastante práctica antes de realizar parciales, lo cuál te facilita entender y aprobar el curso..'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-22T00:00:00+00:00'::TIMESTAMPTZ, '15a30e38ba718583ec1edcc680fff4ac5f161adf5d237d5f42016e523a98e8b2'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'un profe que da las clases cortas, y deja tareas grupales. no explica muy bien pero listo para contestar cualquier duda. y es una persona que sabe demasiado entonces si se aprende'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'Pocos exámenes']::TEXT[], '2026-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'fdd0d821f8586a4b7525dea4104ef3959a31046505ce0d061fe055e8c278b7cd'::TEXT, ARRAY[1708]::BIGINT[]),
    (45::BIGINT, 'No es para todo el mundo, hay que poner mucha atención, es demasiado puntual y estricto con las tardías. Para los exámenes a veces le da vuelta a las mesas pero no se levanta del escritorio. Pero creo que es muy buen profe, califica suave.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2026-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'e219b5921bad955c5d6e109cc5f7d0b51c48061cd6b71c592846452f8b927824'::TEXT, ARRAY[2394]::BIGINT[]),
    (45::BIGINT, 'Es muy bueno, hay que hacer bastantes trabajos, pero califica suave y explica bastante bien. Lo único negativo es que es un toque desordenado con el cronograma, fuera de eso lo recomiendo.'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Brinda apoyo']::TEXT[], '2025-06-28T00:00:00+00:00'::TIMESTAMPTZ, '997c677b96b6ae1d2ad53269838e4811d9cd624eb93ee2d09b3e8a7ccda0807c'::TEXT, ARRAY[92]::BIGINT[]),
    (45::BIGINT, 'Siempre está dispuesto a ayudar, suele hacer muchas prácticas que sirven para el examen. Pero da retroalimentación de las tareas y la calificación de los trabajos mucho tiempo después. Lo recomiendo solo si lleva muchos créditos, no califica duro.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2025-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c4e2c287850cc4b4f6a65ce33c00d82fce26b76e6c7b8886b164508cf5f03b8b'::TEXT, ARRAY[92]::BIGINT[]),
    (45::BIGINT, 'El profesor a veces no explica cosas que entran en el examen. Los examenes para que los revisa arbitrariamente porque puede ser que dos personas tengan la misma tarea y a uno le pone 100 y al otro 90 sin decir por qué.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2025-02-02T00:00:00+00:00'::TIMESTAMPTZ, '9196ef4fbc95b170d938e84a6054160749cb40537f47bd0355b8b04d45aa29e1'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'El profe es muy simpatico. El problema es que no explica bien y se enrreda. Mucho trabajo en grupos y se pasa muy facil. Nunca revisa las tareas y te pone 100 con solo entregarla. En terminos de recomnedacion, no se depende del estudiante, pero personalmente no llevaria otra vez con el.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2024-11-17T00:00:00+00:00'::TIMESTAMPTZ, '591e253ae141f7076702135a4df259806790f68f108f845c9dee462a42a05e10'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Los exámenes tienen cosas que no fueron vistas en clase, ni en las prácticas. Las tareas siempre tienen cosas que no se han visto en la clase.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '69122b53b2fc499913ca0fb4db6c8df5173234a11592e0cfa01ffdbf4f084484'::TEXT, ARRAY[2394]::BIGINT[]),
    (45::BIGINT, 'Le encanta el curso de contabilidad de costos y se nota por que los estudiantes entiendan la materia'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2023-06-17T00:00:00+00:00'::TIMESTAMPTZ, 'b90cd526b7ddb15bd9580253a040c3866514a629e32afde69a46673475994a7c'::TEXT, ARRAY[2394]::BIGINT[]),
    (45::BIGINT, 'En general es un buen profe, brinda apoyo si uno lo solicita y deja muchos ejercicios de tarea lo cual ayuda a ir más preparado al examen. Sin embargo el principal problema es que da muy poco tiempo para resolver el examen que incluye varios ejercicios, y nunca accede a extender el tiempo.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2023-06-16T00:00:00+00:00'::TIMESTAMPTZ, '1a4fed6c6c0a43b7b71d34727340f8c820ec67827b94b01f88089d1ca9cfd249'::TEXT, ARRAY[2394]::BIGINT[]),
    (45::BIGINT, 'Los examenes son largos pero parecidos a prácticas. Es serio pero no cae mal, está abierto a ayudar y hasta da su telefóno para dudas, se nota que sabe mucho. Casi no da clases presenciales, exámenes sí son presenciales. La materia es ruda, deja varias tareas'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2022-12-23T00:00:00+00:00'::TIMESTAMPTZ, '0b457d5253cf0043fa080e850a091429a564531b67a76454a233587b508224dd'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Es un buen profesor, sabe bastante y explica bien, las prácticas son muy parecidas a los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria']::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, '15a2288d80bfd7f18836d7e0bb4707fb5ebdfae111fbad7ba7ddbd90319213e9'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-10T00:00:00+00:00'::TIMESTAMPTZ, '31866faa7a2573b3831b4c6c19b24e6836d831741f3128864ba61b0bcbeaef27'::TEXT, ARRAY[290]::BIGINT[]),
    (45::BIGINT, 'Es un muy buen profe, la materia por su naturaleza puede ser compleja pero manda bastantes tareas y se aprende bien. Puede ser difícil seguirle el ritmo pero es muy abierto a contestar dudas y hacer ejemplos hasta que entienda.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Brinda apoyo']::TEXT[], '2022-01-30T00:00:00+00:00'::TIMESTAMPTZ, 'a5644c44b0336348752e0355da89b81c070f8efbe76f67269d307d04226dceab'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'El profe es preciso, es importante realizar todas las tareas ya que son muy similares al examen. Abarca todas las dudas que se expongan y es amable'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Muchos proyectos grupales']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '3c97468683f26259f7c959784e4a21a43b25ecd780e9a1c05f37d29bbda888c9'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Es un gran profesor, explica rápido, ayuda mucho, las practicas son largas pero prácticamente son iguales a los exámenes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Aspectos de calificación claros', 'Deja trabajos largos']::TEXT[], '2021-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'fd761b28f9deb17741fd8e9494739d2acabface9f260b8a4bb840cf457458093'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'El profe sabe mucho pero explica algo rápido, si usted no tiene ninguna base de conta se le va a complicar acomodarse al ritmo. Deja muchas prácticas, pero son básicamente las que saldrán en el examen. Le gusta la participación en clase, e incluso llama al azar para que expliquen algún ejercicio.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'La participación importa', 'Clases largas']::TEXT[], '2021-11-20T00:00:00+00:00'::TIMESTAMPTZ, '17f1f29f4c712eba86a2c70afc7eba63b3f3dee64ee43273e02bf45a3dc1b484'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-14T00:00:00+00:00'::TIMESTAMPTZ, '94c976d0282d5f9cfd52f01ac029fda0924b63fdd8002b2c112e462332882a38'::TEXT, ARRAY[2948]::BIGINT[]),
    (45::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-05-18T00:00:00+00:00'::TIMESTAMPTZ, '9cfcf67346a739e18cde18f40eb39c4c6e72e6c3087af6bf9fa7d9093ecb93a5'::TEXT, ARRAY[212, 91]::BIGINT[]),
    (45::BIGINT, 'Es muy buen profesor, entiende al estudiante al final del semestre pues no le exige tanto, las practicas son el mismo examen , si le gusta que uno participe, de hecho llama en clase al azar pero con que digas lo que entiendes basta, trata siempre de que entiendas la materia'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'La participación importa', 'Asistencia obligatoria']::TEXT[], '2021-01-29T00:00:00+00:00'::TIMESTAMPTZ, '7482563738d18f5a7c859e0615a023354dedb6342e2d01b33665b83e69605a3a'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'El profe sabe demasiado. Deja tareas casi todas las semanas y acostumbra a subir la solución, los exámenes son prácticamente las practicas de clases. Lo recomiendo 100%. Ayuda a quien necesite y explica las veces que sea necesario. Si puede matricular con él no lo piense 2 veces.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2020-08-25T00:00:00+00:00'::TIMESTAMPTZ, '647cc92134658991d91deadfdc16aa30797e0f21cebe18ff9508293523995bfe'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Sabe mucho de la materia y la explica muy claramente. Ayuda mucho a quien lo necesite. Hizo que la clase me interesara bastante. Examenes y tareas sencillas, el proyecto es fácil. En la clase virtual sigue siendo muy bueno. El es super buena gente y respetuoso. El mejor, 100% Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-01T00:00:00+00:00'::TIMESTAMPTZ, '0a4e6f9ee71b189640a2a0dff8fd35e3e8c8c3e9af95a42823c1208b8ae333f5'::TEXT, ARRAY[1707]::BIGINT[]),
    (45::BIGINT, 'Explica un poco enredado'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2017-06-12T00:00:00+00:00'::TIMESTAMPTZ, '938694471a8971326749c4f9afcf7502a086ba3a9eede74edf8496b284831684'::TEXT, ARRAY[294]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
